package com.yumi.cafe.controller;
import com.yumi.cafe.model.MenuItem;import com.yumi.cafe.repository.MenuItemRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/menu") public class MenuController{private final MenuItemRepository repo;private final String key;public MenuController(MenuItemRepository r,@Value("${app.admin.key}")String k){repo=r;key=k;}private void auth(String supplied){if(supplied==null||!supplied.equals(key))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid admin key");}@GetMapping public List<MenuItem> active(){return repo.findByActiveTrueOrderByCategoryAscNameAsc();}@GetMapping("/all") public List<MenuItem> all(@RequestHeader(value="X-Admin-Key",required=false)String k){auth(k);return repo.findAllByOrderByCategoryAscNameAsc();}@PostMapping public MenuItem create(@RequestHeader(value="X-Admin-Key",required=false)String k,@RequestBody MenuItem m){auth(k);m.setActive(true);return repo.save(m);}@PutMapping("/{id}") public MenuItem update(@RequestHeader(value="X-Admin-Key",required=false)String k,@PathVariable Long id,@RequestBody MenuItem body){auth(k);MenuItem m=repo.findById(id).orElseThrow();m.setName(body.getName());m.setCategory(body.getCategory());m.setPrice(body.getPrice());m.setMediumPrice(body.getMediumPrice());m.setActive(body.isActive());return repo.save(m);}}
